from __future__ import annotations

from exo import *
from exo.libs.memories import DRAM
from exo.API_scheduling import *

# Base, straightforward implementation mirroring the PolyBench doitgen kernel.
# We keep the same signature used by the C driver; the 'sum' buffer is a
# temporary workspace of length np.
@proc
def kernel_doitgen_base(
    nr: size,
    nq: size,
    np: size,
    A: DATA_TYPE[nr, nq, np] @ DRAM,
    C4: DATA_TYPE[np, np] @ DRAM,
    sum: DATA_TYPE[np] @ DRAM,
):
    for r in seq(0, nr):
        for q in seq(0, nq):
            # For each (r, q), compute one matrix-vector product:
            #   sum[p] = sum_s A[r, q, s] * C4[s, p]
            for p in seq(0, np):
                sum[p] = 0.0
                for s in seq(0, np):
                    sum[p] += A[r, q, s] * C4[s, p]
            for p in seq(0, np):
                A[r, q, p] = sum[p]


# ---------------------- Scheduling / optimization -----------------------------

# Small compile-time constant used to partially unroll the reduction over 's'.
# This can be tuned per micro-architecture (e.g., 2, 4, 8) to balance code size
# and instruction-level parallelism.
UNROLL_S: int = 4

# Start from the base kernel.
p = kernel_doitgen_base

# 1) Partially unroll the inner reduction loop over 's'.
#
#    We first split the 's' loop into (s_outer, s_inner) with a fixed
#    s_inner extent of UNROLL_S. The tail iterations (np % UNROLL_S) are
#    handled automatically via a remainder loop, so semantics are preserved.
s_loop = p.find_loop("s")
p = divide_loop(p, s_loop, UNROLL_S, ("s_outer", "s_inner"))
p = unroll_loop(p, p.find_loop("s_inner"))

# 2) Parallelize the computation over 'p'.
#
#    For a fixed (r, q), each iteration of the first 'p' loop:
#       - writes sum[p],
#       - reads A[r, q, s] and C4[s, p],
#       - does not touch sum[p'] for p' != p.
#    Likewise, the second 'p' loop writes A[r, q, p] from sum[p] independently
#    for each p. Therefore there are no loop-carried dependences across 'p',
#    and OpenMP-style parallelization is safe.
p_loop_0 = p.find_loop("p")        # first p-loop (compute dot products into sum)
p = parallelize_loop(p, p_loop_0)

p_loop_1 = p.find_loop("p #1")     # second p-loop (write results back to A)
p = parallelize_loop(p, p_loop_1)

# 3) Expose the optimized kernel under the name expected by the C driver.
kernel_doitgen = rename(p, "kernel_doitgen")
