from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# ---------------------------------------------------------------------------
# Doitgen kernel
#
# Computes, for each (r, q, p):
#   A[r, q, p] = sum_{s=0}^{np-1} A[r, q, s] * C4[s, p]
#
# Optimizations built into the object code:
#   * Use a 2D scratch buffer sum_local[r, p] instead of a 3D sum.
#   * For the inner accumulation we iterate with `s` outer and `p` inner:
#         for s: a = A[r, q, s]; for p: sum_local[r, p] += a * C4[s, p]
#     so that C4 is read in row-major order (contiguous in `p`) and
#     A[r, q, s] is loaded once per (r, q, s) and reused across all p.
#   * The external 1D buffer `sum_ext` is kept for interface compatibility.
#     At the end we store into it the last computed sum vector, matching
#     the behavior of the original 1D sum-based formulation.
# ---------------------------------------------------------------------------

@proc
def kernel_doitgen(
    nr: size,
    nq: size,
    np: size,
    A: DATA_TYPE[nr, nq, np] @ DRAM,
    C4: DATA_TYPE[np, np] @ DRAM,
    sum_ext: DATA_TYPE[np] @ DRAM,
):
    # Basic sanity: problem sizes must be positive.
    assert nr > 0
    assert nq > 0
    assert np > 0

    # Scratch buffer: one row per r, reused across all q for that r.
    # This keeps memory usage low while allowing safe parallelization over r.
    sum_local: DATA_TYPE[nr, np] @ DRAM

    for r in seq(0, nr):
        for q in seq(0, nq):
            # Zero partial sums for this (r, q).
            for p in seq(0, np):
                sum_local[r, p] = 0.0

            # Accumulate:
            #   sum_local[r, p] = Σ_s A[r, q, s] * C4[s, p]
            # We iterate s outer / p inner to:
            #   * stream C4[s, p] in row-major order (good cache locality),
            #   * load A[r, q, s] once and reuse for all p.
            for s in seq(0, np):
                a_rqs: DATA_TYPE
                a_rqs = A[r, q, s]
                for p in seq(0, np):
                    sum_local[r, p] += a_rqs * C4[s, p]

            # Write the result back into A.
            for p in seq(0, np):
                A[r, q, p] = sum_local[r, p]

