#    to an OpenMP parallel for, exploiting up to all available cores.
_sched = parallelize_loop(_sched, "r")

# 2) Simplify to clean up the IR after transformations.
_sched = simplify(_sched)

# Expose the optimized version under the original name.
kernel_doitgen = _sched
